I=[]
I.append(R(6359828,"ग्रिल्ड पेपर स्टेक टोस्टाडा","इन टोस्टाडा के ऊपर हफ़्ते के दिनों के ताज़ा और स्वादिष्ट भोजन के लिए पतले कटे, ग्रिल किए हुए कम चर्बी वाले स्टेक, मलाईदार एवोकाडो, चेरी टमाटर और चटपटी सालसा वर्दे डाली जाती है। स्टेक और टॉर्टिला को ग्रिल पैन या बाहरी ग्रिल पर ग्रिल करें, और अतिरिक्त तीखेपन के लिए जलापेनो मिर्च के कुछ स्लाइस डालें।","4","2 टोस्टाडा",
["12 औंस कम चर्बी वाला स्टेक (आई राउंड रोस्ट, सर्लोइन टिप, टॉप राउंड स्टेक, या बॉटम राउंड स्टेक)","1/4 छोटा चम्मच नमक (कोशर)","1/2 छोटा चम्मच काली मिर्च","2 स्प्रे, 0.5 ग्राम नॉनस्टिक कुकिंग स्प्रे","8 छोटी मक्के की टॉर्टिला (6 इंच)","1/2 कप सालसा वर्दे (टोमाटिलो सालसा)","1 बड़ा एवोकाडो (कटा हुआ)","1 कप चेरी टमाटर (चार भागों में कटे हुए)","1/4 कप ताज़ी धनिया पत्ती (कटी हुई)"],
["ग्रिल करने से 30 मिनट पहले स्टेक को फ़्रिज से निकाल लें। स्टेक पर नमक और काली मिर्च लगाएँ।","इनडोर ग्रिल पैन, कड़ाही या बाहरी ग्रिल को मध्यम-तेज़ आँच पर पहले से गरम करें।","ग्रिल पैन के गरम होने पर, उस पर तेल लगाएँ। स्टेक डालें और हर तरफ़ 6-8 मिनट पकाएँ, जब तक स्टेक मनचाहा पक न जाए। आँच से हटाएँ और प्लेट में एक तरफ़ रख दें; पतली पट्टियों में काटने से पहले 5 मिनट आराम करने दें।","ग्रिल पैन को पेपर टॉवल से पोंछें और उस पर हल्का कुकिंग स्प्रे करें। वापस मध्यम आँच पर रखें।","दो टॉर्टिला ग्रिल पैन पर रखें और बस टोस्ट होने तक 2-3 मिनट ग्रिल करें। पलटें और 2-3 मिनट और टोस्ट करें। निकालें और बाकी टॉर्टिला ग्रिल करें।","टॉर्टिला के ऊपर सालसा वर्दे, कटा स्टेक, एवोकाडो के स्लाइस, कटे टमाटर और धनिया पत्ती डालें।"]))
I.append(R(6360044,"कैरिबियाई बीन डिप","इस डिप को बनाएँ और फ़्रिज में रखें ताकि आप पूरे सप्ताह इसे कुछ ताज़ी सब्ज़ियों के साथ नाश्ते में खा सकें।","8","3½ बड़े चम्मच डिप + 4 अजवाइन की डंडियाँ + 4 गाजर की डंडियाँ",
["1 (15.5 औंस) डिब्बा ऑर्गेनिक काली बीन्स (छनी और धुली हुई)","1/2 मध्यम हैस एवोकाडो (छिला और कटा हुआ)","3 बड़े चम्मच नींबू का रस","2 बड़े चम्मच धनिया पत्ती (मोटे कटे हुए)","1/4 छोटा चम्मच पिसी लाल मिर्च (केयेन)","1/4 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच कोशर नमक","3 डंठल हरी प्याज़ (पतली कटी हुई)","4 डंठल अजवाइन (सेलरी) (आधे कटे हुए)","4 मध्यम गाजर (आधी कटी, छोटी डंडियों में)"],
["हरी प्याज़ को छोड़कर सारी सामग्री को ब्लेंडर में चिकना होने तक प्यूरी करें। ऊपर हरी प्याज़ डालें।","अजवाइन और गाजर की डंडियों के साथ परोसें।"]))
I.append(R(6360759,"सैल्मन और व्हीट बेरी पेस्टो सलाद","व्हीट बेरी गेहूँ के पौधे का दाना है जिसकी बाहरी भूसी हटा दी गई है। इनका स्वाद मेवे जैसा और बनावट चबाने वाली होती है और ये फ़ाइबर, प्रोटीन और आयरन से भरपूर होते हैं। आप इन्हें पहले से एक बैच में बनाकर फ़्रिज में एक सप्ताह तक रख सकते हैं। अगर आपको व्हीट बेरी न मिलें, तो इस रेसिपी में फ़ारो, स्पेल्ट या ब्राउन राइस का उपयोग किया जा सकता है।","2","2 1/4 कप सलाद का मिश्रण और सब्ज़ियाँ + 3 औंस सैल्मन",
["1/2 कप व्हीट बेरी (या फ़ारो)","2, 3-औंस के सैल्मन फ़िलेट","5 1/2 छोटा चम्मच तैयार पेस्टो","2 कप रॉकेट (अरुगुला)","2 कप बेबी पालक (कटा हुआ)","1/2 कप पकी हुई हरी फलियाँ","1/2 कप चेरी टमाटर (आधे कटे हुए)","1 बड़ा चम्मच पाइन नट्स (भुने हुए)","1/4 कप माइक्रोग्रीन्स"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। शीट पैन पर एल्युमिनियम फ़ॉइल बिछाएँ और हल्का कुकिंग स्प्रे करें।","व्हीट बेरी को पैकेट के निर्देशों के अनुसार पकाएँ।","हर सैल्मन फ़िलेट पर आधा छोटा चम्मच पेस्टो लगाएँ। तैयार शीट पैन पर रखें और ओवन में रखें। सैल्मन के 145 डिग्री F तक पहुँचने तक पकाएँ, सैल्मन फ़िलेट की मोटाई के आधार पर लगभग 15–20 मिनट।","जब व्हीट बेरी पक जाएँ, तो उन्हें छान लें और 4 1/2 छोटा चम्मच पेस्टो के साथ मिलाएँ।","पालक और अरुगुला को 2 बड़ी प्लेटों या कटोरों में बाँटें। पत्तों पर पेस्टो का लेप लगाने के लिए व्हीट बेरी मिलाएँ।","हर प्लेट के सलाद के पत्तों के ऊपर 1 सैल्मन फ़िलेट रखें। आधी हरी फलियाँ और टमाटर डालें और हर कटोरे पर पाइन नट्स और माइक्रोग्रीन्स छिड़कें।"]))
I.append(R(6360930,"बटरनट स्क्वैश नूडल्स के साथ परमेसन टोफ़ू","हमारा बटरनट स्क्वैश नूडल्स के साथ परमेसन टोफ़ू आज़माएँ—मधुमेह के अनुकूल एक व्यंजन जो परमेसन से लिपटे टोफ़ू के स्वादिष्ट कुरकुरेपन को बटरनट स्क्वैश नूडल्स की पौष्टिक अच्छाई के साथ जोड़ता है। एक सुंदर रंगीन भोजन के लिए इसे शैम्पेन विनेग्रेट में भुनी हरी फलियों के साथ बनाएँ। डेयरी-मुक्त चीज़ और बिना अंडे वाले मेयो के विकल्पों का उपयोग करके इस व्यंजन को आसानी से वीगन बनाया जा सकता है।","4","7 औंस टोफ़ू और ~2 कप नूडल्स",
["28 औंस एक्स्ट्रा फ़र्म टोफ़ू (छना हुआ और कम से कम 30 मिनट दबाया हुआ)","2 छोटा चम्मच जैतून का तेल (बाँटकर)","1 मध्यम बटरनट स्क्वैश","1/2 छोटा चम्मच इटैलियन सीज़निंग (बाँटकर)","1 औंस कम वसा वाला परमेसन चीज़ (कद्दूकस किया हुआ)","1/4 कप लाइट मेयोनेज़","1/4 छोटा चम्मच प्याज़ पाउडर","1/4 छोटा चम्मच लहसुन पाउडर","1 कप ताज़ी तुलसी (पत्ते पतले कतरे हुए)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर एल्युमिनियम फ़ॉइल बिछाएँ।","हर टोफ़ू ब्लॉक को लंबी तरफ़ से आधा काटें। बेकिंग शीट पर रखें और 1 छोटा चम्मच तेल ऊपर से डालें। 15 मिनट बेक करें, पलटें, फिर 15 मिनट और बेक करें।","इस बीच, स्क्वैश का सख़्त छिलका उतारें। स्क्वैश से नूडल्स काटने के लिए जूलियन पीलर का उपयोग करें।","एक बड़ी कड़ाही को मध्यम आँच पर पहले से गरम करें। 1 छोटा चम्मच तेल, स्क्वैश और ¼ छोटा चम्मच इटैलियन सीज़निंग डालें। बीच-बीच में चलाते हुए स्क्वैश नूडल्स के नरम होने तक, 7–8 मिनट पकाएँ। आँच से हटाएँ, ढक दें और एक तरफ़ रख दें।","एक छोटे कटोरे में परमेसन, मेयो, 1/4 छोटा चम्मच इटैलियन सीज़निंग, प्याज़ पाउडर और लहसुन पाउडर मिलाएँ।","टोफ़ू के 30 मिनट बेक हो जाने के बाद, ओवन से निकालें। ओवन को हाई पर ब्रॉयल पर सेट करें और ओवन की एक रैक को ब्रॉयलर के ठीक नीचे सबसे ऊपर की शेल्फ़ पर रखें।","चीज़ के मिश्रण को टोफ़ू के ऊपर फैलाएँ। वापस ओवन में रखें और टॉपिंग के बुलबुले उठने और भूरा होना शुरू होने तक, 1–2 मिनट ब्रॉयल करें।","स्क्वैश नूडल्स की परत पर मुट्ठी भर ताज़ी तुलसी के साथ परोसें।"]))
I.append(R(6362411,"टर्की और सब्ज़ियों वाला चिली","यह चिली एक बेहतरीन वन-पॉट भोजन है। बीन्स सेहतमंद कार्बोहाइड्रेट देती हैं, टर्की कम चर्बी वाला प्रोटीन देता है, और गाजर, तोरी, प्याज़ और टमाटर सब्ज़ियाँ प्रदान करते हैं। झटपट, आसान, सेहतमंद और सर्दियों के ठंडे दिन के लिए एकदम सही!","8","1 कप",
["1 छोटा प्याज़ (छोटे टुकड़ों में कटा हुआ)","2 मध्यम गाजर (छोटे टुकड़ों में कटी हुई)","1 मध्यम तोरी (ज़ुकिनी) (छोटे टुकड़ों में कटी हुई)","1 कली लहसुन (बारीक कटा हुआ)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","16 औंस कम चर्बी वाला टर्की का कीमा","1 (14.5 औंस) डिब्बा कटे हुए डिब्बाबंद टमाटर","1 (28 औंस) डिब्बा कुचले हुए डिब्बाबंद टमाटर","1 (15.8 औंस) डिब्बा डिब्बाबंद नेवी या ग्रेट नॉर्दर्न बीन्स (धुली और छनी हुई)","1 (15 औंस) डिब्बा राजमा (धुला और छना हुआ)","1/2 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच लाल मिर्च पाउडर","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच लहसुन पाउडर"],
["एक बड़े सूप के बर्तन पर कुकिंग स्प्रे करें। प्याज़, गाजर और तोरी डालें, और मध्यम-तेज़ आँच पर 3-4 मिनट या प्याज़ के पारदर्शी होने तक भूनें। लहसुन डालें और 30 सेकंड और भूनें।","टर्की का कीमा डालें और भूरा होने तक पकाएँ। बाकी सामग्री डालें; अच्छी तरह मिलाएँ और चिली को उबाल आने दें। आँच कम करें और 15-20 मिनट धीमी आँच पर पकाएँ।"]))
I.append(R(6363916,"मसालेदार ग्लेज़ वाले संतरे","मसालेदार शहद ग्लेज़ वाले संतरे एक सरल और आनंददायक मधुमेह के अनुकूल मिठाई है जो संतरे की प्राकृतिक मिठास को गरम और सुगंधित शहद-मसाले के ग्लेज़ के साथ जोड़ती है। रंग और स्वाद के अतिरिक्त स्पर्श के लिए ऊपर ताज़ी कटी पुदीने की पत्तियाँ डालें।","4","1/2 संतरा",
["2 बड़े संतरे (छिले और गोल स्लाइस में कटे हुए)","1 बड़ा चम्मच शहद","1/2 छोटा चम्मच पिसी दालचीनी","1/8 छोटा चम्मच पिसा जायफल","1/8 छोटा चम्मच पिसी अदरक","1/8 छोटा चम्मच नमक","1 टहनी ताज़ा पुदीना (सजाने के लिए, वैकल्पिक)"],
["संतरे छीलें और उन्हें गोल स्लाइस में काटें। कोई भी बीज निकाल दें।","एक छोटे सॉसपैन में धीमी आँच पर शहद, 1 बड़ा चम्मच पानी, पिसी दालचीनी, पिसा जायफल, पिसी अदरक और एक चुटकी समुद्री नमक मिलाएँ। मिश्रण के अच्छी तरह मिलने और गरम होने तक चलाएँ।","संतरे के स्लाइस को परोसने की थाली या अलग-अलग प्लेटों पर सजाएँ।","मसालेदार शहद का ग्लेज़ संतरे के स्लाइस पर डालें, यह सुनिश्चित करते हुए कि हर स्लाइस पर स्वादिष्ट लेप लगे।","संतरे तुरंत परोसें।"]))
I.append(R(6364308,"स्वादिष्ट पकी हुई साग","इस रेसिपी के लिए सरसों, शलगम, स्विस चार्ड, केल या कोलार्ड का साग इस्तेमाल करें!","12","1/2 कप",
["2 पाउंड कोमल साग (ताज़ा)","2 छोटा चम्मच मक्के का तेल","1/2 कप प्याज़ (कटा हुआ)","1 1/4 कप पानी","1 पूरा चिकन बाउलन (क्यूब, कम सोडियम वाला)","1/4 छोटा चम्मच नमक","1 छोटा चम्मच चीनी","1/8 छोटा चम्मच Tabasco सॉस"],
["साग से डंठल और कोई भी पीले पत्ते हटाएँ, फिर साग को अच्छी तरह धोएँ और छान लें।","एक बड़े बर्तन में तेल मध्यम आँच पर गरम करें। प्याज़ डालें और प्याज़ के नरम होने तक भूनें।","बर्तन में साग, पानी और बाउलन डालें। ढकें और उबाल आने दें। आँच धीमी करें और साग के नरम होने तक 30 मिनट, बीच-बीच में चलाते हुए, धीमी आँच पर पकाएँ।","नमक, चीनी और Tabasco सॉस डालें। अच्छी तरह मिलाएँ और अतिरिक्त 5 मिनट धीमी आँच पर पकाएँ। साग का सबसे अच्छा स्वाद निखारने के लिए इसे साइडर सिरके के साथ परोसा जा सकता है।"]))
I.append(R(6364389,"चिकन और एवोकाडो के साथ पालक का सलाद","एक अच्छे सलाद में सब्ज़ियाँ, प्रोटीन, स्वाद और अलग-अलग बनावट चाहिए। इस रेसिपी में चिकन प्रोटीन देता है। एवोकाडो और सूरजमुखी के बीजों के साथ मिलाने पर आपको एकदम सही स्वाद, बनावट और कुरकुरापन मिलता है। यह झटपट और आसान सलाद हल्के और संतोषजनक दोपहर के भोजन के लिए एकदम सही है। यह मील प्रेप के लिए भी बढ़िया है—बस हर हिस्से को अलग डिब्बे में पैक करें, और ड्रेसिंग परोसने से ठीक पहले डालें।","4","2 कप",
["12 औंस बेबी पालक","1 छोटा एवोकाडो (गुठली निकाला और पतले स्लाइस में कटा हुआ)","2 मध्यम रोमा (प्लम) टमाटर (छोटे टुकड़ों में कटे हुए)","1 कप पका हुआ चिकन ब्रेस्ट (छोटे टुकड़ों में कटा हुआ)","4 बड़े चम्मच सूरजमुखी के बीज","6 बड़े चम्मच लाइट रैंच ड्रेसिंग"],
["एक बड़े सलाद कटोरे में पालक, एवोकाडो, टमाटर, चिकन और सूरजमुखी के बीज मिलाएँ। ड्रेसिंग डालें और बराबर लेप के लिए मिलाएँ। या, अगर पहले से तैयार कर रहे हैं, तो सलाद को चार डिब्बों में बाँटें। खाने से ठीक पहले 1 ½ बड़ा चम्मच ड्रेसिंग डालें।"]))
I.append(R(6366362,"जापानी चिकन और पालक राइस बाउल","अनाज, प्रोटीन और सब्ज़ियों वाले बाउल अब लोकप्रिय हैं, और एक बार जब आप इसे चखेंगे, तो समझ जाएँगे क्यों। यह एक पौष्टिक बाउल है जो चिकन सूप के आराम को ताज़ी सब्ज़ियों के रंग और स्वाद के साथ जोड़ता है। आप बाउल को अपनी पसंद या अपने पास मौजूद चीज़ों के अनुसार भी बदल सकते हैं। अगर आपके पास ब्राउन राइस नहीं है, तो आप पके हुए क्विनोआ, फ़ारो या साबुत अनाज के कूसकूस का उपयोग कर सकते हैं। आप अपने बाउल के ऊपर कटा खीरा, कद्दूकस की गाजर या कटी शिमला मिर्च भी डाल सकते हैं। और, अगर आपको तीखा खाना पसंद है, तो लाल मिर्च के फ़्लेक्स बढ़ा दें।","4","1 ½ कप चिकन और सब्ज़ियाँ + 1/2 कप ब्राउन राइस",
["1 पाउंड चिकन ब्रेस्ट (बिना हड्डी, बिना त्वचा वाले आधे भाग, सारी दिखने वाली चर्बी हटाई हुई)","1 डंठल अजवाइन (सेलरी) (चार भागों में कटा हुआ)","1/2 मध्यम प्याज़ (1/2 इंच की फाँकों में कटा हुआ)","2 कली लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच कम सोडियम वाला सोया सॉस","1 छोटा चम्मच राइस विनेगर","1/8 छोटा चम्मच कुटी लाल मिर्च के फ़्लेक्स","3 कप पानी","2 कप बिना नमक मिलाया चिकन स्टॉक (बिना वसा वाला)","2/3 कप ब्राउन राइस","4 कप पालक (हल्का दबाकर भरा हुआ, ताज़े पत्ते, साफ़ किए और मोटे कटे हुए)","4 मध्यम मूली (पतली कटी हुई)","2 डंठल हरी प्याज़ (पतली कटी हुई)","2 छोटा चम्मच तिल (भुने हुए)"],
["चिकन को मध्यम स्लो कुकर में रखें। अजवाइन के टुकड़े, प्याज़ की फाँकें, लहसुन, सोया सॉस, सिरका और तीखी मिर्च के फ़्लेक्स डालें। पानी और चिकन स्टॉक डालें। ढकें और धीमी सेटिंग पर 3 से 5 घंटे, या चिकन के पूरी तरह पकने और चिकन का तापमान 165 F तक पहुँचने तक पकाएँ।","परोसने से लगभग एक घंटा पहले, पैकेट के निर्देशों के अनुसार चावल तैयार करें, नमक और मार्जरीन छोड़कर।","छेदवाले चम्मच से चिकन को स्लो कुकर से निकालें और कटिंग बोर्ड पर रखें। शोरबे को बारीक जाली वाली छन्नी से एक गहरे कटोरे में छानें। गरम शोरबे को वापस स्लो कुकर में डालें। स्लो कुकर को हाई पर करें।","चिकन को निवाले के आकार के टुकड़ों में काटें और स्लो कुकर में गरम शोरबे में वापस मिलाएँ। पालक मिलाएँ। ढकें और हाई पर 15 मिनट पकाएँ।","हर परोसने के कटोरे में 1/2 कप पका ब्राउन राइस डालें। चावल के ऊपर 1 1/2 कप चिकन, पालक और शोरबे का मिश्रण डालें। ऊपर कटी मूली और हरी प्याज़ डालें। तिल छिड़कें।","प्रेशर कुकर का विकल्प: चिकन, अजवाइन, प्याज़, लहसुन, सोया सॉस, सिरका और तीखी मिर्च के फ़्लेक्स प्रेशर कुकर में रखें। पानी और चिकन स्टॉक डालें। ढक्कन कसकर बंद करें। हाई प्रेशर पर 6 मिनट पकाएँ। जल्दी से प्रेशर छोड़ें। चिकन निकालें और कटिंग बोर्ड पर रखें। शोरबा छानें और वापस प्रेशर कुकर में डालें। चिकन को निवाले के आकार के टुकड़ों में काटें और शोरबे में मिलाएँ। प्रेशर कुकर को सौते सेटिंग पर रखें। पालक डालें और बार-बार चलाते हुए, पालक के पकने तक 3 से 5 मिनट पकाएँ। रेसिपी के निर्देशों के अनुसार आगे बढ़ें, चिकन और पालक को पके ब्राउन राइस पर डालें और ऊपर मूली, हरी प्याज़ और तिल डालें।"]))
I.append(R(6367232,"ग्लूटेन-फ़्री क्विनोआ चॉकलेट चिप कुकीज़","आप क्विनोआ से बनी कुकी आज़माने में हिचकिचा सकते हैं, लेकिन ये उच्च फ़ाइबर वाली कुकीज़ स्वादिष्ट और बनाने में आसान हैं! बनावट पारंपरिक कुकी से थोड़ी ज़्यादा घनी है, लेकिन आप इन कुकीज़ को बिना अपराध-बोध के खा सकते हैं!","30","1 कुकी",
["3 बड़े चम्मच Smart Balance मार्जरीन (नरम की हुई)","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट","1 बड़ा अंडा","1/4 कप कम या बिना कैलोरी वाला स्वीटनर","1 कप पुराने ढंग के रोल्ड ओट्स (ग्लूटेन-फ़्री)","2 कप पका हुआ क्विनोआ (ठंडा किया हुआ)","1/2 कप बेकिंग मिक्स ((जैसे Pamela’s), ग्लूटेन-फ़्री)","1/4 कप मिनी चॉकलेट चिप्स"],
["ओवन को 350 डिग्री पर पहले से गरम करें। बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","एक बड़े कटोरे में मार्जरीन, वनीला, अंडा और कम या बिना कैलोरी वाला स्वीटनर फेंटकर मिलाएँ। अच्छी तरह मिलने तक मिलाएँ।","मिश्रण में ओट्स, क्विनोआ और बेकिंग मिक्स डालें और अच्छी तरह चलाएँ। चॉकलेट चिप्स धीरे से मिलाएँ।","बड़े चम्मच से बेकिंग शीट पर गिराएँ। 15 मिनट बेक करें।","जाली पर ठंडा करें और ठंडा होने पर वायुरोधी डिब्बे में रखें।"]))
I.append(R(6368072,"चार सामग्री वाली बादाम बटर कुकी","बनाने में झटपट और आसान, ये चार सामग्री वाली बादाम बटर कुकीज़ अगली बार जब आपको कुछ मीठा खाने का मन हो तो पसंदीदा बनाने लायक रेसिपी हैं। मधुमेह के अनुकूल और कम कार्बोहाइड्रेट वाली, ये निश्चित रूप से परिवार की पसंदीदा मिठाई होंगी।","12","1 कुकी",
["1 कप बादाम बटर","1 बड़ा अंडा (हल्का फेंटा हुआ)","1/3 कप शुगर-फ़्री बेकिंग चीनी का विकल्प","1 छोटा चम्मच वनीला एक्स्ट्रैक्ट"],
["अपने ओवन को 350 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर बेकिंग पेपर बिछाएँ।","एक मिक्सिंग कटोरे में बादाम बटर, अंडा, चीनी और वनीला एक्स्ट्रैक्ट मिलाएँ। सारी सामग्री के अच्छी तरह मिलने तक मिलाएँ।","ठंडे किए आटे के बड़े चम्मच जितने हिस्से निकालें और उन्हें गोले बना लें। गोलों को तैयार बेकिंग शीट पर रखें, हर एक के बीच जगह छोड़ते हुए। अगर आटा बेलने के लिए बहुत नरम है, तो उसे 30 मिनट फ़्रिज में रखें ताकि वह सख़्त हो जाए।","काँटे से हर कुकी के गोले को धीरे से दबाएँ ताकि आड़ा-तिरछा निशान बन जाए।","पहले से गरम किए ओवन में लगभग 10 मिनट या किनारों के सुनहरा भूरा होने तक बेक करें।","कुकीज़ को बेकिंग शीट पर कुछ मिनट ठंडा होने दें, फिर उन्हें पूरी तरह ठंडा करने के लिए जाली पर रखें।"]))
I.append(R(6368221,"शतावरी, शिमला मिर्च और मशरूम का सौते","बिना स्टार्च वाली सब्ज़ियाँ—जैसे शतावरी (एस्पैरेगस), शिमला मिर्च और मशरूम—विटामिन और खनिजों से भरपूर होती हैं, फिर भी कैलोरी और कार्बोहाइड्रेट में कम होती हैं। अपनी आधी प्लेट को बिना स्टार्च वाली सब्ज़ियों से भरने के लिए इस रेसिपी जैसे सरल, स्वादिष्ट विचारों का उपयोग करें!","7","1/2 कप",
["1 1/2 बड़ा चम्मच जैतून का तेल","1 पाउंड शतावरी (एस्पैरेगस) (सिरे कटे और तिहाई में कटे हुए)","1/2 कप लाल प्याज़ (कटा हुआ)","8 औंस क्रेमिनी (बेबी बेला) मशरूम (कटे हुए)","1 मध्यम लाल शिमला मिर्च (कटी हुई)","1 कली लहसुन (बारीक कटा हुआ)"],
["एक बड़े सौते पैन या वोक में जैतून का तेल मध्यम-तेज़ आँच पर गरम करें। शतावरी, प्याज़, मशरूम और लाल शिमला मिर्च डालें और बार-बार चलाते हुए 15-18 मिनट पकाएँ।","पैन में लहसुन डालें और 1 मिनट पकाएँ। सब्ज़ियों और लहसुन को मिलाने के लिए चलाएँ।"]))
I.append(R(6369435,"टोफ़ू और एडामामे सलाद","हमारे टोफ़ू और एडामामे सलाद के साथ पौधों पर आधारित पूर्णता की दुनिया में कदम रखें। मुलायम टोफ़ू, जीवंत एडामामे और कुरकुरी सब्ज़ियों का रंगीन संग्रह स्वादों की एक ताज़गी भरी सिम्फ़नी बनाते हैं। घर पर बनी एक आनंददायक ड्रेसिंग में मिलाया गया, यह सलाद आपको हर निवाले की पौष्टिक अच्छाई का आनंद लेने के लिए आमंत्रित करता है।","4","1 कप",
["14 औंस सख़्त टोफ़ू (सख़्त, दबाया हुआ और चौकोर टुकड़ों में कटा हुआ)","1 कप जमे हुए एडामामे (छिले हुए)","1 कप लाल पत्तागोभी (पतली कटी हुई)","1 कप गाजर (पतली लंबी कतरों में कटी हुई)","1/4 कप हरे जैतून (कटे हुए)","1 बड़ा चम्मच तिल","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच राइस विनेगर","1 बड़ा चम्मच तिल का तेल","1 बड़ा चम्मच पीनट बटर","1 छोटा चम्मच मेपल सिरप","1 छोटा चम्मच ताज़ी अदरक (कद्दूकस की हुई)","1 कली लहसुन (बारीक कटा हुआ)","1/4 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["एक बड़े कटोरे में चौकोर कटा टोफ़ू, छिले एडामामे, पतली कटी लाल पत्तागोभी, पतली कतरों में कटी गाजर, कटी हरी प्याज़ और तिल मिलाएँ।","एक छोटे कटोरे में कम सोडियम वाला सोया सॉस, राइस विनेगर, तिल का तेल, पीनट बटर, मेपल सिरप, कद्दूकस की ताज़ी अदरक, बारीक कटा लहसुन, नमक और काली मिर्च को फेंटकर मिलाएँ।","ड्रेसिंग को सलाद पर डालें और बराबर लेप के लिए धीरे से मिलाएँ।"]))
I.append(R(6371783,"सैल्मन और राइस बाउल","इन सैल्मन और राइस बाउल को आपकी पसंदीदा सब्ज़ियों के साथ बदला जा सकता है। सैल्मन, चावल और ताज़ी सब्ज़ियों का मेल हफ़्ते के दिनों के लिए एक सेहतमंद और संतोषजनक भोजन बनाता है।","4","1 सैल्मन फ़िलेट, 1 कप मिश्रण",
["16 औंस सैल्मन (4 फ़िलेट, हर एक 4 औंस का)","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","2 छोटा चम्मच शहद","1 बड़ा चम्मच तिल का तेल","2 छोटा चम्मच ताज़ी अदरक (बारीक कटी हुई)","2 कली लहसुन (बारीक कटा हुआ)","2 कप पका ब्राउन राइस","1 कप ब्रोकोली (भाप में पकी हुई)","1 कप गाजर (कद्दूकस की हुई)","1/4 मध्यम एवोकाडो (कटा हुआ)","2 डंठल हरी प्याज़ (कटी हुई, परोसने के लिए)"],
["एक छोटे कटोरे में सोया सॉस, शहद, तिल का तेल, बारीक कटी अदरक और बारीक कटा लहसुन फेंटकर सॉस बनाएँ।","सैल्मन पर कुछ सॉस लगाएँ।","एक बड़ी कड़ाही को मध्यम-तेज़ आँच पर गरम करें और सैल्मन को पूरी तरह पकने तक, हर तरफ़ लगभग 4 मिनट सेकें।","सैल्मन के ऊपर और मैरिनेड लगाएँ।","ब्राउन राइस, भाप में पकी ब्रोकोली, सैल्मन और एवोकाडो से बाउल बनाएँ। ऊपर से सॉस डालें। हरी प्याज़ से समाप्त करें।"]))
I.append(R(6372211,"सेहतमंद टैको डिप","इस टैको डिप के पारंपरिक संस्करण में वसा बहुत ज़्यादा होती है और उसमें सावर क्रीम और क्रीम चीज़ का उपयोग होता है। हम ज़्यादा सेहतमंद वसा (एवोकाडो) और कम वसा वाले चीज़ का उपयोग करते हैं ताकि स्वाद से कोई समझौता किए बिना आपकी ढेर सारी कैलोरी बच सके। यह डिप टेलगेटिंग और फ़ुटबॉल के मौसम के लिए बढ़िया है!","24","1 ढेर लगा बड़ा चम्मच",
["1 (16 औंस) डिब्बा रीफ़्राइड बीन्स (बिना वसा वाली)","2 छोटा चम्मच लाल मिर्च पाउडर","1/2 छोटा चम्मच जीरा","1/4 छोटा चम्मच लहसुन पाउडर","1 1/2 मध्यम एवोकाडो (मसला हुआ)","1/3 कप सालसा","1 बड़ा टमाटर (बीज निकाला और छोटे टुकड़ों में कटा हुआ)","1 कप रोमेन लेट्यूस (कतरा हुआ)","1 कप कद्दूकस किया मैक्सिकन चीज़ का मिश्रण"],
["एक मध्यम कटोरे में रीफ़्राइड बीन्स, लाल मिर्च पाउडर, जीरा और लहसुन पाउडर मिलाएँ।","रीफ़्राइड बीन्स को एक मध्यम परोसने की थाली पर बराबर फैलाएँ। मसला एवोकाडो बीन्स के ऊपर बराबर फैलाएँ।","सालसा को एवोकाडो के ऊपर बराबर फैलाएँ। ऊपर टमाटर, कतरा लेट्यूस और कद्दूकस किया चीज़ डालें।","डिप को अपनी पसंद के बेक्ड टॉर्टिला चिप्स, काली बीन चिप्स या जिकामा के स्लाइस के साथ परोसें। अगर आप ग्लूटेन-फ़्री आहार लेते हैं, तो सुनिश्चित करें कि टॉर्टिला चिप्स बिना मसाले वाले और ग्लूटेन-फ़्री हों।"]))
save(6,I)
